// Dialog: React Aria (modal with trapped focus, Esc closes, focus returns to the trigger). Generated by shadcn and trimmed.
// Two ways in: inside a DialogTrigger (ConfirmButton), or controlled with isOpen (opened from a Menu item).
import { t } from "@zorel/i18n"
import type { ReactNode } from "react"
import { Dialog as DialogPrimitive, DialogTrigger, Heading, Modal, ModalOverlay } from "react-aria-components"
import { cn } from "@/lib/utils"
import { Button, type ButtonProps } from "./button"

const overlay =
  "fixed inset-0 z-50 flex items-center justify-center bg-overlay p-4 data-entering:animate-in data-entering:fade-in-0 data-exiting:animate-out data-exiting:fade-out-0 motion-reduce:animate-none"
const sheet = "flex max-h-full w-full flex-col rounded-sheet border border-strong bg-canvas p-6 text-fg shadow-float outline-none data-entering:animate-in data-entering:fade-in-0 data-entering:zoom-in-[0.97] data-exiting:animate-out data-exiting:fade-out-0 data-exiting:zoom-out-[0.98] data-exiting:duration-100 motion-reduce:animate-none"

type Body = (close: () => void) => ReactNode

function Content({ title, children }: { title: string; children: Body }) {
  return (
    <DialogPrimitive className="flex min-h-0 flex-1 flex-col gap-4 outline-none">
      {({ close }) => (
        <>
          <Heading slot="title" className="text-title font-semibold">
            {title}
          </Heading>
          {/* A long body scrolls inside the sheet; the title stays. */}
          <div className="-mx-6 flex min-h-0 flex-1 flex-col gap-4 overflow-auto px-6">{children(close)}</div>
        </>
      )}
    </DialogPrimitive>
  )
}

// sm 384px (a confirmation), lg 576px (a form), xl 672px (a form with choices side by side: a new routine).
const WIDTH = { sm: "max-w-sm", lg: "max-w-xl", xl: "max-w-2xl" } as const
// anchor "top": a dialog whose parts differ in height (tabs) keeps its title still and grows downward.
export function Dialog({ title, children, isOpen, onOpenChange, size = "sm", anchor = "center" }: { title: string; children: Body; isOpen?: boolean; onOpenChange?: (open: boolean) => void; size?: keyof typeof WIDTH; anchor?: "center" | "top" }) {
  return (
    <ModalOverlay isDismissable className={cn(overlay, anchor === "top" && "items-start sm:pt-[8vh]")} {...(isOpen !== undefined && { isOpen })} {...(onOpenChange && { onOpenChange })}>
      <Modal className={`${sheet} ${WIDTH[size]}`}>
        <Content title={title}>{children}</Content>
      </Modal>
    </ModalOverlay>
  )
}

// Cancel + the destructive action, for both entry points.
function ConfirmActions({ close, confirmLabel, onConfirm }: { close: () => void; confirmLabel: string; onConfirm: () => void }) {
  return (
    <div className="flex justify-end gap-2">
      <Button variant="ghost" onPress={close}>
        {t("common.cancel")}
      </Button>
      <Button
        variant="destructive"
        autoFocus
        onPress={() => {
          close()
          onConfirm()
        }}
      >
        {confirmLabel}
      </Button>
    </div>
  )
}

// Button that asks for confirmation before a destructive action (replaces window.confirm).
export function ConfirmButton({
  title,
  description,
  confirmLabel = t("common.delete"),
  onConfirm,
  ...button
}: Omit<ButtonProps, "onPress"> & { title: string; description?: ReactNode; confirmLabel?: string; onConfirm: () => void }) {
  return (
    <DialogTrigger>
      <Button {...button} />
      <Dialog title={title}>
        {(close) => (
          <>
            {description && <p className="text-base text-muted">{description}</p>}
            <ConfirmActions close={close} confirmLabel={confirmLabel} onConfirm={onConfirm} />
          </>
        )}
      </Dialog>
    </DialogTrigger>
  )
}

// The same confirmation, opened from code (e.g. a "Delete" menu item).
export function ConfirmDialog({
  isOpen,
  onOpenChange,
  title,
  description,
  confirmLabel = t("common.delete"),
  onConfirm
}: { isOpen: boolean; onOpenChange: (open: boolean) => void; title: string; description?: ReactNode; confirmLabel?: string; onConfirm: () => void }) {
  return (
    <Dialog title={title} isOpen={isOpen} onOpenChange={onOpenChange}>
      {(close) => (
        <>
          {description && <p className="text-base text-muted">{description}</p>}
          <ConfirmActions close={close} confirmLabel={confirmLabel} onConfirm={onConfirm} />
        </>
      )}
    </Dialog>
  )
}
